import XCTest
@testable import Recast

/// Checks the Swift port of the conversion matrix against answers generated by the Python engine
/// (Fixtures/matrix_cases.json, kept current by engine/tests/test_swift_parity.py).
final class FormatMatrixTests: XCTestCase {
    private struct Case: Decodable {
        struct Expected: Decodable {
            struct T: Decodable { let ext: String; let label: String }
            let targets: [T]
            let unsupported_files: [String]
            let can_combine_pdf: Bool
            let mixed_no_common: Bool
        }
        let files: [String]
        let expected: Expected
    }

    func testMatchesPythonEngineForEveryCase() throws {
        let url = try XCTUnwrap(Bundle(for: Self.self).url(forResource: "matrix_cases", withExtension: "json"))
        let cases = try JSONDecoder().decode([Case].self, from: Data(contentsOf: url))
        XCTAssertGreaterThan(cases.count, 200)
        var mismatches: [String] = []
        for c in cases {
            let got = FormatMatrix.shared.analyze(paths: c.files)
            let ok = got.targets.map(\.ext) == c.expected.targets.map(\.ext)
                && got.targets.map(\.label) == c.expected.targets.map(\.label)
                && got.unsupportedPaths == c.expected.unsupported_files
                && got.canCombinePDF == c.expected.can_combine_pdf
                && got.mixedNoCommon == c.expected.mixed_no_common
            if !ok { mismatches.append(c.files.joined(separator: ", ")) }
        }
        XCTAssertTrue(mismatches.isEmpty, "Swift and Python disagree for: \(mismatches.prefix(10))")
    }

    func testAliases() {
        let m = FormatMatrix.shared
        XCTAssertEqual(m.normalize("JPEG"), "jpg")
        XCTAssertEqual(m.normalize(".heif"), "heic")
        XCTAssertEqual(m.normalize("..jpg"), "jpg")   // matches Python's lstrip(".")
        XCTAssertEqual(m.group(of: "m4v"), "video")
        XCTAssertNil(m.group(of: "xyz"))
    }
}
